        control_vals = []
        for c in range(1, 11):
            try:
                v = float(sheet.cell_value(r, c))
                patient_vals.append(v)
            except:
                pass
        for c in range(11, 21):
            try:
                v = float(sheet.cell_value(r, c))
                control_vals.append(v)
            except:
                pass
