# Check miR-95 in results
print("\n=== hsa-miR-95 in results ===")
with open('/workspace/mirna_results.tsv') as f:
    for line in f:
        if 'miR-95' in line and 'miR-95*' not in line and 'miR-9*' not in line:
            parts = line.strip().split('\t')
            print(f"  miRNA: {parts[0]}, p={parts[1]}, bonf={parts[2]}, by={parts[3]}")
